import {themes as prismThemes} from 'prism-react-renderer';
import type {Config} from '@docusaurus/types';
import type * as Preset from '@docusaurus/preset-classic';

import {ROUTES, GITHUB_REPO, EDIT_URL, SITE_TITLE} from './src/constants';

// Runs in Node.js — no client-side code (no browser APIs, no JSX).
//
// Four-plugin IA: docs/user/ (CLI + getting-started + engine reference),
// docs/methodology/ (measurement methodology + interpretation),
// docs/api/ (auto-generated Python library reference),
// docs/architecture/ (pipeline internals + contributor onboarding).
// Changelog: served as a standalone React page (src/pages/changelog.tsx)
// importing CHANGELOG.md directly; symlinked at docs/changelog.md for
// direct-GitHub viewing.
//
// Content lives in docs/ at the repo root; this Docusaurus instance lives
// in website/ and points its plugins at ../docs/<subdir>. .product/ is
// gitignored project-decision storage and is deliberately not referenced.

const config: Config = {
  title: SITE_TITLE,
  tagline: 'Energy & efficiency measurement for LLM inference',

  future: {
    v4: true,
  },

  // baseUrl defaults to GH Pages subpath (henrycgbaker.github.io/llenergymeasure/);
  // override via DOCUSAURUS_BASE_URL=/ for hosts that serve at root (CF Pages
  // previews + production at *.pages.dev). url is left as the GH Pages origin
  // so canonical URLs always point at the production source of truth, even
  // when rendered on a preview host.
  url: 'https://henrycgbaker.github.io',
  baseUrl: process.env.DOCUSAURUS_BASE_URL ?? '/llenergymeasure/',

  organizationName: 'henrycgbaker',
  projectName: 'llenergymeasure',

  onBrokenLinks: 'throw',

  markdown: {
    // Treat .md files as plain CommonMark (not MDX). Docs in this repo use
    // standard markdown features only — HTML comments, GFM tables, code
    // blocks — and don't need JSX. CommonMark mode is more permissive.
    format: 'md',
    hooks: {
      onBrokenMarkdownLinks: 'throw',
    },
  },

  i18n: {
    defaultLocale: 'en',
    locales: ['en'],
  },

  presets: [
    [
      'classic',
      {
        docs: {
          path: '../docs/user',
          routeBasePath: 'docs',
          sidebarPath: './sidebars.ts',
          editUrl: EDIT_URL,
        },
        blog: false,
        theme: {
          customCss: './src/css/custom.css',
        },
      } satisfies Preset.Options,
    ],
  ],

  plugins: [
    [
      '@docusaurus/plugin-content-docs',
      {
        id: 'methodology',
        path: '../docs/methodology',
        routeBasePath: 'methodology',
        sidebarPath: './sidebarsMethodology.ts',
        editUrl: EDIT_URL,
      },
    ],
    [
      '@docusaurus/plugin-content-docs',
      {
        id: 'api',
        path: '../docs/api',
        routeBasePath: 'api',
        sidebarPath: './sidebarsApi.ts',
        // Source content is auto-generated by scripts/generate_api_docs.py
        // — Edit-this-page links go to the source-of-truth docstrings in
        // src/llenergymeasure/, not to the generated markdown.
        editUrl: undefined,
      },
    ],
    [
      '@docusaurus/plugin-content-docs',
      {
        id: 'architecture',
        path: '../docs/architecture',
        routeBasePath: 'architecture',
        sidebarPath: './sidebarsArchitecture.ts',
        editUrl: EDIT_URL,
      },
    ],
    [
      require.resolve('@easyops-cn/docusaurus-search-local'),
      {
        hashed: true,
        language: ['en'],
        docsDir: [
          '../docs/user',
          '../docs/methodology',
          '../docs/api',
          '../docs/architecture',
        ],
        docsRouteBasePath: ['docs', 'methodology', 'api', 'architecture'],
        indexBlog: false,
      },
    ],
  ],

  themeConfig: {
    colorMode: {
      respectPrefersColorScheme: true,
    },
    navbar: {
      title: SITE_TITLE,
      items: [
        {to: ROUTES.userGuide, label: 'Docs', position: 'left'},
        {to: ROUTES.methodology, label: 'Methodology', position: 'left'},
        {to: ROUTES.api, label: 'API', position: 'left'},
        {to: ROUTES.architecture, label: 'Architecture', position: 'left'},
        {to: '/changelog', label: 'Changelog', position: 'left'},
        {href: GITHUB_REPO, label: 'GitHub', position: 'right'},
      ],
    },
    footer: {
      style: 'dark',
      links: [
        {
          title: 'Use',
          items: [
            {label: 'Installation', to: ROUTES.userGuide},
            {label: 'CLI reference', to: '/docs/cli-reference'},
            {label: 'Library API', to: ROUTES.api},
            {label: 'Troubleshooting', to: '/docs/troubleshooting'},
          ],
        },
        {
          title: 'Learn',
          items: [
            {label: 'Methodology', to: ROUTES.methodology},
            {label: 'Energy measurement', to: '/methodology/energy-measurement'},
            {label: 'Architecture overview', to: ROUTES.architecture},
          ],
        },
        {
          title: 'More',
          items: [
            {label: 'GitHub', href: GITHUB_REPO},
          ],
        },
      ],
      copyright: `Copyright © ${new Date().getFullYear()} ${SITE_TITLE} contributors`,
    },
    prism: {
      theme: prismThemes.github,
      darkTheme: prismThemes.dracula,
    },
  } satisfies Preset.ThemeConfig,
};

export default config;
